package net.civeira.phylax.features.access.usermfaenrollment.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.usermfaenrollment.domain.UserMfaEnrollment;
import net.civeira.phylax.features.access.usermfaenrollment.domain.event.UserMfaEnrollmentEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserMfaEnrollmentEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserMfaEnrollmentEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserMfaEnrollment entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
